<?php require __DIR__.'/../../bootstrap/app.php';role_required('technical');$db=Database::get();$uid=(int)user()['id'];
$next=['accepted'=>'in_progress_none','rejected'=>'approved','traveling'=>'','arrived'=>'','working'=>'in_progress','completed'=>'completed'];
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['availability'])){verify_csrf();$av=$_POST['availability'];$sp=mb_substr(trim((string)($_POST['specialization']??'')),0,160);if(in_array($av,['available','busy','unavailable'],true)){$db->prepare("INSERT INTO technician_profiles(user_id,specialization,availability_status) VALUES(?,?,?) ON DUPLICATE KEY UPDATE availability_status=VALUES(availability_status),specialization=IF(VALUES(specialization)='',specialization,VALUES(specialization))")->execute([$uid,$sp,$av]);notice('Availability and skills saved.');}go('technical/jobs.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$st=$_POST['status']??'';
 if(isset($next[$st])){$a=$db->prepare("SELECT request_id FROM service_assignments WHERE id=? AND technician_id=?");$a->execute([$id,$uid]);$rid=$a->fetchColumn();
  if($rid){$db->prepare("UPDATE service_assignments SET status=? WHERE id=?")->execute([$st,$id]);$rs=$next[$st];if($rs&&$rs!=='in_progress_none')$db->prepare("UPDATE service_requests SET status=? WHERE id=?")->execute([$rs,$rid]);audit('job '.$st,'assignment',$id);notice('Job updated.');}}
 go('technical/jobs.php');}
$q=$db->prepare("SELECT a.id,a.status,a.assigned_at,s.name sname,sr.description,sr.address,sr.preferred_date,u.name cname,u.phone FROM service_assignments a JOIN service_requests sr ON sr.id=a.request_id JOIN services s ON s.id=sr.service_id JOIN users u ON u.id=sr.customer_id WHERE a.technician_id=? ORDER BY a.id DESC");$q->execute([$uid]);$rows=$q->fetchAll();
$flow=['offered'=>['accepted'=>'Accept','rejected'=>'Decline'],'accepted'=>['traveling'=>'On my way'],'traveling'=>['arrived'=>'Arrived'],'arrived'=>['working'=>'Start work'],'working'=>['completed'=>'Mark completed']];
$w=$db->prepare("SELECT available_balance,pending_balance FROM technician_wallets WHERE technician_id=?");$w->execute([$uid]);$w=$w->fetch()?:['available_balance'=>0,'pending_balance'=>0];$tp=$db->prepare("SELECT specialization,availability_status FROM technician_profiles WHERE user_id=?");$tp->execute([$uid]);$tp=$tp->fetch()?:['specialization'=>'','availability_status'=>'unavailable'];$title='My jobs';require __DIR__.'/../../app/Views/header.php';?><section class="section"><div class="container"><h1>My jobs</h1><form method="post" class="cardx mb-3"><?=csrf_field()?><h5>My availability and skills</h5><p class="mb-2"><small>The admin uses this to choose the right person for each request. Jobs in progress also show you as working.</small></p><input class="form-control mb-2" name="specialization" maxlength="160" placeholder="Your skills, e.g. electrical wiring, solar, CCTV, plumbing" value="<?=e((string)$tp['specialization'])?>"><?php foreach(['available'=>'I am free','busy'=>'I am busy','unavailable'=>'Unavailable'] as $v=>$l):?><button name="availability" value="<?=$v?>" class="btn btn-sm <?=$tp['availability_status']===$v?'btn-dark':'btn-outline-dark'?>"><?=$l?></button> <?php endforeach;?></form><div class="cardx mb-3">Wallet: available <b><?=e($w['available_balance'])?> ETB</b> · pending <b><?=e($w['pending_balance'])?> ETB</b></div><p><a href="<?=e(url('dashboard.php'))?>">← Dashboard</a></p>
<?php if(!$rows):?><p>No jobs assigned yet.</p><?php endif;?><?php foreach($rows as $r):?><div class="cardx mb-3"><b><?=e($r['sname'])?></b> · <span class="badge bg-secondary"><?=e($r['status'])?></span><p class="mb-1 mt-2"><?=nl2br(e($r['description']))?></p><small>Customer: <?=e($r['cname'])?> · <?=e((string)$r['phone'])?> · Address: <?=e($r['address'])?> · Preferred: <?=e((string)$r['preferred_date'])?></small>
<?php if(!empty($flow[$r['status']])):?><form method="post" class="mt-2"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><?php foreach($flow[$r['status']] as $v=>$l):?><button name="status" value="<?=$v?>" class="btn btn-sm <?=$v==='rejected'?'btn-outline-danger':'btn-dark'?>"><?=$l?></button> <?php endforeach;?></form><?php endif;?></div><?php endforeach;?></div></section><?php require __DIR__.'/../../app/Views/footer.php';?>